DUT.Declaration:
{attribute 'pack_mode' := '1'}
TYPE ST_EpsonExternalState :
STRUCT
    Valid                 : BOOL;                 // Snapshot gültig
    Sequence              : UDINT;                // Version des Snapshots
    AutoMode              : BOOL;                 // Anlage im Automatikmodus
    SafetyPermissive      : BOOL;                 // Bewegungserlaubnis (kein Safety-Kanal!)
    Transfer              : ST_EpsonTransferState;
    Press                 : ST_EpsonPressState;
    ToolStation           : ST_EpsonToolStationState;
    Genmark               : ST_EpsonRobotState;
    Staeubli              : ST_EpsonRobotState;
END_STRUCT
END_TYPE
